import assert from 'node:assert/strict';
import fs from 'node:fs';
import {setup,runtime,workspace} from './finance-workflow-db.mjs';
import {readFinanceJourney} from '../../app/lib/finance-workflows.ts';
import {dispatchFinanceOperation} from '../../app/lib/finance-workflow-provider.ts';
export async function financeWorkflowConnected({db,database,shiftId,maker,checker,applicant,client}){
 const t=database.prepare('SELECT * FROM shift_timesheets WHERE shift_id=?').get(shiftId),b=database.prepare('SELECT * FROM bookings WHERE id=?').get(t.booking_id);
 const x=await setup({db,database,bookingId:b.id,officerId:t.officer_id,seed:false,actors:{maker:{...maker,owner:true},reviewer:checker,officer:applicant,client}});
 await x.run({action:'open_order',id:'connected-order',bookingId:b.id,clientUser:client.userId});
 const frames=[];const capture=async label=>frames.push({label,at:new Date().toISOString(),documents:(await readFinanceJourney(db,applicant,runtime,workspace)).records.filter(r=>r.kind==='document').map(r=>({id:r.id,version:r.version,financialState:r.financialState,document:r.data})),balances:database.prepare('SELECT account,balance FROM finance_balances WHERE workspace_id=? ORDER BY account').all(workspace)});
 const total=b.client_price_cents;assert.ok(total>t.gross_wage_cents);
 for(const [id,amount] of [['receipt-a',Math.floor(total/2)],['receipt-b',total-Math.floor(total/2)]]){await x.run({action:'prepare_collection',id,orderId:'connected-order',amount});await x.settle(id);}
 await x.run({action:'allocate_funds',orderId:'connected-order',companyId:t.employer_id,amount:total});
 const payroll=await x.run({action:'recognize_payroll',id:'connected-payroll',orderId:'connected-order',ownerUser:applicant.userId,sources:[{id:t.id}]});const liability=payroll.liabilities[0],net=x.record(liability).net;
 await assert.rejects(x.run({action:'recognize_payroll',id:'reuse',orderId:'connected-order',ownerUser:applicant.userId,sources:[{id:t.id}]}),/immutable|UNIQUE/);
 await x.run({action:'approve_destination',id:'destination',ownerUser:applicant.userId,recipientCode:'SIM-APPROVED-RECIPIENT'});
 await x.run({action:'prepare_payout',id:'payout',liabilityId:liability,destinationId:'destination',amount:net});x.provider.timeout=true;await dispatchFinanceOperation(db,x.actors.maker,runtime,workspace,'payout',x.provider);await assert.rejects(x.run({action:'prepare_payout',id:'unsafe',liabilityId:liability,destinationId:'destination',amount:net,replaces:'payout'}),/unpaid|Replacement/);x.provider.timeout=false;await x.settle('payout','failed',{recover:true});assert.equal(x.balance('liability:'+liability),net);
 await x.run({action:'prepare_payout',id:'replacement',liabilityId:liability,destinationId:'destination',amount:net,replaces:'payout'});await x.settle('replacement');await capture('Independently reconciled payment');assert.equal(x.balance('liability:'+liability),0);assert.equal((await readFinanceJourney(db,applicant,runtime,workspace,'statement:connected-payroll')).records[0].financialState,'paid');
 await x.settle('replacement','reversed',{recover:true});await capture('Final reversal: original statement preserved');assert.equal(x.balance('liability:'+liability),net);assert.equal(x.record('replacement').reference,'lokd-sbx-'+workspace+'-replacement');await assert.rejects(x.run({action:'prepare_payout',id:'second-reuse',liabilityId:liability,destinationId:'destination',amount:net,replaces:'payout'}),/immutable|UNIQUE/);
 await x.run({action:'prepare_payout',id:'replacement-reversed',liabilityId:liability,destinationId:'destination',amount:net,replaces:'replacement'});await x.settle('replacement-reversed');
 const original=database.prepare("SELECT data_json FROM finance_records WHERE id='statement:connected-payroll'").get().data_json;
 await x.run({action:'correct_payroll',payrollId:'connected-payroll',segments:[{id:liability,gross:t.gross_wage_cents+20000}],reason:'Fictional underpayment correction'});assert.equal(x.balance('liability:'+liability),17000);await x.run({action:'prepare_payout',id:'underpayment',liabilityId:liability,destinationId:'destination',amount:17000});await x.settle('underpayment');await capture('Corrected statement and subsequent settlement');
 await x.run({action:'correct_payroll',payrollId:'connected-payroll',segments:[{id:liability,gross:t.gross_wage_cents}],reason:'Fictional overpayment correction'});assert.equal(x.balance('liability:'+liability),-17000);assert.equal(database.prepare("SELECT data_json FROM finance_records WHERE id='statement:connected-payroll'").get().data_json,original);assert.equal(database.prepare("SELECT count(*) AS n FROM finance_records WHERE kind='document' AND id LIKE 'statement:connected-payroll:correction:%'").get().n,2);
 await capture('Overpayment recorded as recoverable; original and corrections retained');if(process.env.FINANCE_EVIDENCE_OUTPUT)fs.writeFileSync(process.env.FINANCE_EVIDENCE_OUTPUT,JSON.stringify({mode:'simulator',policyVersion:'lokd-sandbox-completion-v1',source:'actual connected application service handler',frames},null,2));
 assert.equal(database.prepare('SELECT sum(balance) AS n FROM finance_balances').get().n,0);assert.equal(database.prepare('SELECT enabled FROM payment_live_control').get().enabled,0);return x;
}
export async function exportedPayrollAdjustment({db,database,itemId,maker,checker,applicant,client}){
 const {createFinanceWorkspace,applyFinanceCommand}=await import('../../app/lib/finance-workflow-store.ts'),{prepareFinanceCommand,FINANCE_SANDBOX_POLICY}=await import('../../app/lib/finance-workflows.ts');const workspace='sbx-exported-adjustment';const actors=[{userId:maker.userId,role:'preparer',limit:100000000},{userId:checker.userId,role:'reviewer',limit:100000000},{userId:applicant.userId,role:'officer',limit:100000000}];await createFinanceWorkspace(db,{...maker,owner:true},runtime,workspace,FINANCE_SANDBOX_POLICY,actors);let n=0;const run=async input=>{const p=await prepareFinanceCommand(db,maker,runtime,workspace,input,'export-adjustment-'+(++n));return applyFinanceCommand(db,checker,runtime,workspace,p.commandId,p.digest,'approved','Independently checked actual exported source in the isolated sandbox');};
 const item=database.prepare('SELECT * FROM payroll_items WHERE id=?').get(itemId),source=database.prepare('SELECT t.* FROM pay_item_sources s JOIN shift_timesheets t ON t.id=s.timesheet_id WHERE s.payroll_item_id=?').get(itemId),original=database.prepare('SELECT payload_json FROM production_payroll_snapshots WHERE run_id=?').get(item.payroll_run_id).payload_json;
 await run({action:'open_order',id:'export-order',bookingId:source.booking_id,clientUser:client.userId});await run({action:'adopt_exported_payroll',id:'adopted',itemId,orderId:'export-order',ownerUser:applicant.userId});await run({action:'correct_payroll',payrollId:'adopted',segments:[{id:'adopted:0',gross:item.gross_wage_cents+10000}],reason:'Explicit fictional post-export correction policy'});
 const {DeterministicFinanceProvider,financeSignature,acceptFinanceWebhook,attestFinanceBank}=await import('../../app/lib/finance-workflow-provider.ts');const provider=new DeterministicFinanceProvider();
 const record=id=>JSON.parse(database.prepare('SELECT data_json FROM finance_current_records WHERE workspace_id=? AND id=?').get(workspace,id).data_json);
 const settle=async(id,recover=false)=>{await dispatchFinanceOperation(db,maker,runtime,workspace,id,provider,recover);const evidence=provider.result(record(id)),eventId='export-evidence-'+(++n),raw=JSON.stringify({workspace,operationId:id,eventId,evidence});await acceptFinanceWebhook(db,runtime,raw,await financeSignature(raw,runtime.FINANCE_SIMULATOR_KEY));await attestFinanceBank(db,checker,runtime,workspace,id,'bank:'+eventId,evidence);await run({action:'reconcile_operation',operationId:id});};
 const total=database.prepare('SELECT client_price_cents FROM bookings WHERE id=?').get(source.booking_id).client_price_cents;
 await run({action:'prepare_collection',id:'export-collection',orderId:'export-order',amount:total});await settle('export-collection');await run({action:'allocate_funds',orderId:'export-order',companyId:source.employer_id,amount:total});
 await run({action:'approve_destination',id:'export-destination',ownerUser:applicant.userId,recipientCode:'SIM-EXPORTED-OFFICER'});
 const corrected=record('adopted:0');await run({action:'prepare_payout',id:'export-corrected-payment',liabilityId:'adopted:0',destinationId:'export-destination',amount:corrected.net});provider.timeout=true;await dispatchFinanceOperation(db,maker,runtime,workspace,'export-corrected-payment',provider);provider.timeout=false;await settle('export-corrected-payment',true);
 assert.equal(provider.calls.filter(c=>c.method==='POST'&&c.reference===record('export-corrected-payment').reference).length,1);
 await run({action:'approve_destination',id:'export-tax-destination',ownerUser:applicant.userId,recipientCode:'SIM-EXPORTED-TAX',purpose:'tax'});const taxes=corrected.tax+corrected.deduction+corrected.levy;if(taxes){await run({action:'prepare_tax_payout',id:'export-tax-payment',liabilityId:'adopted:0',destinationId:'export-tax-destination',amount:taxes});await settle('export-tax-payment');}
 for(const account of ['liability:adopted:0','tax:adopted:0'])assert.equal(database.prepare('SELECT balance FROM finance_balances WHERE workspace_id=? AND account=?').get(workspace,account).balance,0);
 assert.equal((await readFinanceJourney(db,applicant,runtime,workspace,'statement:adopted:correction:1')).records[0].financialState,'paid');
 assert.equal(database.prepare('SELECT payload_json FROM production_payroll_snapshots WHERE run_id=?').get(item.payroll_run_id).payload_json,original);assert.equal(JSON.parse(database.prepare("SELECT data_json FROM finance_current_records WHERE workspace_id=? AND id='adopted'").get(workspace).data_json).originalPayrollItem,itemId);assert.equal(database.prepare("SELECT count(*) AS n FROM finance_records WHERE workspace_id=? AND kind='document' AND id='statement:adopted:correction:1'").get(workspace).n,1);assert.equal(database.prepare('SELECT sum(balance) AS n FROM finance_balances WHERE workspace_id=?').get(workspace).n,0);
}
